-- CMA 第2次レベル オリジナル正誤問題（100問）
-- tools/questions.py から自動生成。直接編集せず questions.py を直して python3 tools/build_seed.py を実行
on conflict (id) do update set subject=excluded.subject, unit=excluded.unit, point_code=excluded.point_code,
  point_title=excluded.point_title, level=excluded.level, stem=excluded.stem, answer=excluded.answer,
  explanation=excluded.explanation, sort=excluded.sort, active=true;
